// Story mode bust expressions (OWNER_APPROVED_ADAPTATION 2026-11-11): drawn
// variants of the story's recurring partners, made from each partner's own
// Database hero art (text + that image as the only inputs), so a speaker's face
// changes with the line. Pure data: no imports. Generated by the story art
// pipeline (story-vn-art-20261111/expressions, encode step); `face` is the head
// square [cx, cy, size] in the variant's own pixels, carried over from the
// Database art by matching the two silhouettes.
//
// A mood without its own drawing (and every partner not listed) keeps the
// Database art and its procedural mood motion.

/** Which drawn expression a line's mood shows. */
export const STORY_VN_MOOD_EXPRESSION = Object.freeze({
  happy: "happy", angry: "angry", sad: "sad", shock: "shock", serious: "serious", think: "serious"
});

const freezeDeep = value => {
  if (value && typeof value === "object") { for (const item of Object.values(value)) freezeDeep(item); return Object.freeze(value); }
  return value;
};

