/** The drawn expression for a species and a line mood, or null to keep the Database art. */
export function storyVnExpression(speciesIndex, mood) {
  const expression = STORY_VN_MOOD_EXPRESSION[mood];
  const art = expression ? STORY_VN_EXPRESSIONS[speciesIndex]?.[expression] : null;
  return art ? Object.freeze({ ...art, expression }) : null;
}
